{
    "name": "Patient Intake Form",
    "description": "Comprehensive patient intake form for new patients",
    "formType": "INTAKE",
    "category": "PATIENT_REGISTRATION",
    "isActive": true,
    "formStructure": {
        "version": "1.0",
        "sections": [
            {
                "id": "personal_info",
                "title": "Personal Information",
                "fields": [
                    {
                        "id": "first_name",
                        "type": "text",
                        "label": "First Name",
                        "required": true,
                        "validation": {
                            "minLength": 2,
                            "maxLength": 50
                        }
                    },
                    {
                        "id": "last_name",
                        "type": "text",
                        "label": "Last Name",
                        "required": true,
                        "validation": {
                            "minLength": 2,
                            "maxLength": 50
                        }
                    },
                    {
                        "id": "dob",
                        "type": "date",
                        "label": "Date of Birth",
                        "required": true
                    }
                ]
            },
            {
                "id": "medical_history",
                "title": "Medical History",
                "fields": [
                    {
                        "id": "allergies",
                        "type": "textarea",
                        "label": "Known Allergies",
                        "required": false,
                        "validation": {
                            "maxLength": 1000
                        }
                    },
                    {
                        "id": "current_medications",
                        "type": "textarea",
                        "label": "Current Medications",
                        "required": false,
                        "validation": {
                            "maxLength": 1000
                        }
                    }
                ]
            }
        ]
    },
    "complianceSettings": {
        "hipaaCompliant": true,
        "auditTrail": true,
        "dataRetentionDays": 2555,
        "encryptionRequired": true
    },
    "accessLevel": "STANDARD",
    "tags": ["intake", "patient", "registration"]
}

