{
    "forms": [
        {
            "name": "Patient Consent Form",
            "description": "General patient consent for treatment",
            "formType": "CONSENT",
            "category": "LEGAL",
            "isActive": true,
            "formStructure": {
                "version": "1.0",
                "sections": [
                    {
                        "id": "consent",
                        "title": "Treatment Consent",
                        "fields": [
                            {
                                "id": "patient_signature",
                                "type": "signature",
                                "label": "Patient Signature",
                                "required": true
                            },
                            {
                                "id": "consent_date",
                                "type": "date",
                                "label": "Date of Consent",
                                "required": true
                            }
                        ]
                    }
                ]
            },
            "complianceSettings": {
                "hipaaCompliant": true,
                "auditTrail": true,
                "dataRetentionDays": 2555,
                "encryptionRequired": true
            },
            "accessLevel": "STANDARD",
            "tags": ["consent", "legal"]
        },
        {
            "name": "Emergency Contact Form",
            "description": "Emergency contact information form",
            "formType": "INFORMATION",
            "category": "PATIENT_REGISTRATION",
            "isActive": true,
            "formStructure": {
                "version": "1.0",
                "sections": [
                    {
                        "id": "emergency_contact",
                        "title": "Emergency Contact Information",
                        "fields": [
                            {
                                "id": "contact_name",
                                "type": "text",
                                "label": "Emergency Contact Name",
                                "required": true
                            },
                            {
                                "id": "contact_phone",
                                "type": "tel",
                                "label": "Phone Number",
                                "required": true
                            }
                        ]
                    }
                ]
            },
            "accessLevel": "STANDARD",
            "tags": ["emergency", "contact"]
        }
    ]
}
